param([Parameter(Position=0)][string]$Root,[Parameter(Position=1)][string]$ProjectId,[Parameter(Position=2,ValueFromRemainingArguments=$true)][string[]]$Files)
$ErrorActionPreference='Stop';$results=@();$findings=@();$functions=@();$calls=@();$dangerous=('Invoke'+'-Expression')
foreach($relative in $Files){$target=[IO.Path]::GetFullPath((Join-Path $Root $relative));$rootFull=[IO.Path]::GetFullPath($Root);if(-not $target.StartsWith($rootFull,[StringComparison]::OrdinalIgnoreCase)){throw 'Analysis path escapes project root.'};$tokens=$null;$errors=$null;$ast=[Management.Automation.Language.Parser]::ParseFile($target,[ref]$tokens,[ref]$errors);$content=[IO.File]::ReadAllText($target);$hash=[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData([Text.Encoding]::UTF8.GetBytes($content))).ToLowerInvariant();$results+=@{file=$relative;sha256=$hash;astType=$ast.GetType().Name;tokenCount=$tokens.Count;parseErrors=@($errors|ForEach-Object{@{message=$_.Message;start=$_.Extent.StartOffset;end=$_.Extent.EndOffset}})};$functionNodes=$ast.FindAll({param($node)$node -is [Management.Automation.Language.FunctionDefinitionAst]},$true);foreach($fn in $functionNodes){$functions+=@{id="$relative#$($fn.Name)";file=$relative;start=$fn.Extent.StartOffset;end=$fn.Extent.EndOffset;parameters=@();sources=@();sinks=@()}};$commandNodes=$ast.FindAll({param($node)$node -is [Management.Automation.Language.CommandAst]},$true);foreach($cmd in $commandNodes){$name=$cmd.GetCommandName();$calls+=@{caller=$null;calleeText=$name;target=$null;file=$relative;start=$cmd.Extent.StartOffset;end=$cmd.Extent.EndOffset};if($name -eq $dangerous){$findings+=@{schemaVersion=1;projectId=$ProjectId;language='powershell';kind='semantic-dynamic-command';file=$relative;boundary="$relative`:$($cmd.Extent.StartOffset)-$($cmd.Extent.EndOffset)";start=$cmd.Extent.StartOffset;end=$cmd.Extent.EndOffset;baseSha256=$hash;toolId='powershell-native-parser';toolVersion=$PSVersionTable.PSVersion.ToString();callee=$name;proofStageSatisfied=$false;promotionAuthorized=$false}}}}
@{schemaVersion=1;projectId=$ProjectId;adapter=@{id='powershell-native-parser';version=$PSVersionTable.PSVersion.ToString()};files=$results;diagnostics=@($results.parseErrors);functions=$functions;calls=$calls;interproceduralPaths=@();findings=$findings}|ConvertTo-Json -Depth 12 -Compress
